import org.junit.Test;
import ch.jalu.configme.configurationdata.PropertyListBuilder;
import ch.jalu.configme.properties.Property;
import ch.jalu.configme.exception.ConfigMeException;

import java.util.List;

import static org.junit.Assert.*;

public class PropertyListBuilderTest {

    @Test(expected = ConfigMeException.class)
    public void addNullPropertyTest() {
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();

        // Attempt to add a null property, which should throw an exception
        propertyListBuilder.add(null);
    }

    @Test
    public void addValidPropertyTest() {
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();
        Property<?> property = new Property<String>("sample.path", "default value");

        // Add a valid property, which should not throw an exception
        propertyListBuilder.add(property);

        // Fetch the current property list to confirm it has been added
        List<Property<?>> propertyList = propertyListBuilder.create();

        assertTrue("The property list should contain the added property", propertyList.contains(property));
    }

    @Test
    public void createEmptyPropertyListTest() {
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();

        // Fetch the current property list, which should be empty as no properties have been added
        List<Property<?>> propertyList = propertyListBuilder.create();

        assertTrue("The property list should be empty", propertyList.isEmpty());
    }

    @Test
    public void getRootEntriesEmptyTest() {
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();

        // Fetch the root entries, which should be empty as no properties have been added
        Map<String, Object> rootEntries = propertyListBuilder.getRootEntries();

        assertTrue("The root entries should be empty", rootEntries.isEmpty());
    }

    @Test
    public void getRootEntriesTest() {
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();

        // Add some properties
        Property<?> property1 = new Property<String>("sample.path1", "default value1");
        Property<?> property2 = new Property<String>("sample.path2", "default value2");
        propertyListBuilder.add(property1);
        propertyListBuilder.add(property2);

        // Fetch the root entries, which should now include the properties that were added
        Map<String, Object> rootEntries = propertyListBuilder.getRootEntries();

        assertTrue("The root entries should contain the keys of the added properties",
                rootEntries.containsKey("sample.path1") && rootEntries.containsKey("sample.path2"));
    }
}
